// ── Bulk Upload: loads SheetJS (xlsx parsing/writing) from a CDN on first use,
// the same on-demand <script> pattern used above for Firebase — keeps the app
// a single file with no npm install step for Nikhil to run.
let _xlsxPromise = null;
const loadXLSX = () => {
  if (window.XLSX) return Promise.resolve(window.XLSX);
  if (_xlsxPromise) return _xlsxPromise;
  _xlsxPromise = new Promise((resolve, reject) => {
    const src = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
    const existing = document.querySelector(`script[src="${src}"]`);
    const done = () => { if (window.XLSX) resolve(window.XLSX); else reject(new Error("XLSX failed to load")); };
    if (existing) {
      if (existing.dataset.xlsxLoaded === "true") done();
      else existing.addEventListener("load", done);
      return;
    }
    const s = document.createElement("script"); s.src = src;
    s.onload = () => { s.dataset.xlsxLoaded = "true"; done(); };
    s.onerror = () => { _xlsxPromise = null; reject(new Error("Could not load spreadsheet library — check your connection.")); };
    document.head.appendChild(s);
  });
  return _xlsxPromise;
};

