// ── Supabase Storage upload ─────────────────────────────────────────────────
// Converts a base64 data: URL into an actual uploaded file in the "site-images"
// bucket and returns its public URL. Used everywhere an image previously went
// straight into the database as base64 — products, categories, blog posts,
// PCB/remote reference images. Falls back to returning the original dataUrl
// unchanged if the upload fails, so a network hiccup never blocks someone
// from saving their work (the image just stays base64 for that one save,
// and can be picked up by a later migration pass).
const STORAGE_BUCKET = "site-images";
const uploadImageToStorage = async (dataUrl, folder="uploads") => {
  try{
    if(!dataUrl||!dataUrl.startsWith("data:")) return dataUrl; // already a real URL — nothing to do
    const res=await fetch(dataUrl);
    const blob=await res.blob();
    const ext=(blob.type.split("/")[1]||"jpg").replace("jpeg","jpg");
    const path=`${folder}/${Date.now()}-${Math.random().toString(36).slice(2,9)}.${ext}`;
    const up=await fetch(`${SB_URL}/storage/v1/object/${STORAGE_BUCKET}/${path}`,{
      method:"POST",
      headers:{apikey:SB_KEY,Authorization:`Bearer ${SB_KEY}`,"Content-Type":blob.type||"image/jpeg"},
      body:blob,
    });
    if(!up.ok) throw new Error(`storage upload failed (${up.status})`);
    return `${SB_URL}/storage/v1/object/public/${STORAGE_BUCKET}/${path}`;
  }catch(e){
    console.warn("Image upload to storage failed, keeping base64 for now:",e.message);
    return dataUrl;
  }
};

const slugify = (s) => (s||"").toString().toLowerCase().trim()
  .replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,80) || "item";

// ── SITE-WIDE SEO — sets <title>, meta description, Open Graph tags, the
// canonical link, and an optional JSON-LD block for whatever page is on
// screen (Shop categories/products, individual Wiring Diagram pages, etc).
// Runs client-side after React renders, which helps Google's JS-rendering
// pass and any crawler that executes JS — but NOT link-preview bots
// (WhatsApp, Facebook, iMessage) since those only ever read the raw,
// un-rendered HTML.
const SITE_URL = "https://pcbcare.in";
const setSEO = ({title,description,path,image,jsonLd,jsonLdId="page-jsonld",noindex=false}) => {
  try{
    if(title) document.title = title;
    const ensureMeta=(attr,key,content)=>{
      let el=document.querySelector(`meta[${attr}="${key}"]`);
      if(!el){ el=document.createElement("meta"); el.setAttribute(attr,key); document.head.appendChild(el); }
      el.setAttribute("content",content||"");
    };
    // Private/account-specific pages (a user's own submitted requests, etc.)
    // shouldn't try to rank at all — indexing thin, per-user boilerplate only
    // dilutes crawl budget and can look like duplicate content to Google.
    ensureMeta("name","robots",noindex?"noindex, nofollow":"index, follow");
    if(description){ ensureMeta("name","description",description); ensureMeta("property","og:description",description); }
    if(title) ensureMeta("property","og:title",title);
    if(image) ensureMeta("property","og:image",image);
    ensureMeta("property","og:type",jsonLd?"product":"website");
    const url = path?`${SITE_URL}${path}`:window.location.href;
    ensureMeta("property","og:url",url);
    let canon=document.querySelector('link[rel="canonical"]');
    if(!canon){ canon=document.createElement("link"); canon.setAttribute("rel","canonical"); document.head.appendChild(canon); }
    canon.setAttribute("href",url);
    let ld=document.getElementById(jsonLdId);
    if(jsonLd){
      if(!ld){ ld=document.createElement("script"); ld.type="application/ld+json"; ld.id=jsonLdId; document.head.appendChild(ld); }
      ld.textContent=JSON.stringify(jsonLd);
    }else if(ld){
      ld.remove();
    }
  }catch{}
};
const clearSEO = (jsonLdId="page-jsonld") => {
  try{
    document.title="PCB Care";
    const ld=document.getElementById(jsonLdId); if(ld) ld.remove();
    const canon=document.querySelector('link[rel="canonical"]'); if(canon) canon.remove();
    const robots=document.querySelector('meta[name="robots"]'); if(robots) robots.setAttribute("content","index, follow");
  }catch{}
};

