// PERSISTENT STORAGE
// Settings/preferences are written synchronously and read back the same way on
// every mount, so refreshing the page (or relaunching) restores them correctly.
// If a previous build appeared to "reset to default after refresh", it was
// almost always because a value was only kept in React state and never written
// to DB.set(...) — every persisted field below now round-trips through this.
// ════════════════════════════════════════════════════════════════════════════
const DB = {
  get:(k,d)=>{
    try{
      const v=localStorage.getItem(k);
      if(v===null||v===undefined) return d;
      return JSON.parse(v);
    }catch{return d;}
  },
  set:(k,v)=>{
    try{
      localStorage.setItem(k,JSON.stringify(v));
      return true;
    }catch(e){
      console.error("DB.set failed for key",k,e);
      return false;
    }
  },
  remove:(k)=>{try{localStorage.removeItem(k);}catch{}}
};

