// ── Shared Google sign-in — ALWAYS uses signInWithRedirect, never
// signInWithPopup, on every platform. Popups get silently blocked by mobile
// and embedded browsers whenever the Firebase SDK hasn't 100% finished
// loading by the exact moment the user taps the button — timing we can
// reduce (preloading at boot) but never fully guarantee, since a fast tap
// right after page load can still race the network fetch. A redirect never
// calls window.open() at all, so there's no popup for any browser to block,
// on any device, ever. The result is picked up via getRedirectResult() the
// next time the app mounts (see the REDIRECT_CB_KEY handlers below).
const googleSignIn = async (auth) => {
  const provider = new window.firebase.auth.GoogleAuthProvider();
  await auth.signInWithRedirect(provider);
  return null; // page will reload; caller should not proceed
};

// Stored callback key used to resume after redirect
const REDIRECT_CB_KEY = "pcb_google_redirect_cb"; // "login" | "signup"

const api = async (table,{method="GET",filter="",body=null,prefer=""}={}) => {
  const url = `${SB_URL}/rest/v1/${table}${filter}`;
  const h = {apikey:SB_KEY,Authorization:`Bearer ${SB_KEY}`,"Content-Type":"application/json"};
  if(prefer) h["Prefer"]=prefer;
  const r = await fetch(url,{method,headers:h,body:body?JSON.stringify(body):null});
  const raw = await r.text(); // read once as text; Supabase sends an EMPTY body for prefer:"return=minimal" and for PATCH/DELETE
  if(!r.ok){
    let detail=raw;
    try{const j=JSON.parse(raw);detail=j.message||j.error||raw;}catch{}
    throw new Error(`${table} ${method} failed (${r.status}): ${detail||r.statusText}`);
  }
  if(!raw) return null; // empty body is a valid success case, not a parse error
  try{return JSON.parse(raw);}catch{return null;}
};

// Calls the /api/invoices serverless function — the ONLY path allowed to
// touch invoice data (see invoice_schema.sql: RLS denies the anon key
// entirely on those tables). Attaches the current Firebase ID token so
// the server can verify who's actually asking, rather than trusting
// whatever technician_id the client claims.
const invoicesApi = async (action, payload = {}) => {
  const auth = await initFirebase();
  const currentUser = auth?.currentUser;
  if(!currentUser) throw new Error("Not logged in");
  const idToken = await currentUser.getIdToken();
  const r = await fetch("/api/invoices", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${idToken}` },
    body: JSON.stringify({ action, ...payload }),
  });
  const data = await r.json().catch(() => ({}));
  if(!r.ok) throw new Error(data.error || `Request failed (${r.status})`);
  return data;
};

// Same idea for the two admin-only actions — uses the admin session
// already established by the existing admin login flow rather than a
// Firebase token, matching how the rest of the admin panel is gated.
const invoicesAdminApi = async (action, payload = {}) => {
  const session = DB.get("pcb_admin_session", null);
  const r = await fetch("/api/invoices", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Admin-Session": session?.token || "",
      "X-Admin-Session-Expires": String(session?.expiresAt || ""),
    },
    body: JSON.stringify({ action, ...payload }),
  });
  const data = await r.json().catch(() => ({}));
  if(!r.ok) throw new Error(data.error || `Request failed (${r.status})`);
  return data;
};

